from __future__ import annotations
from dataclasses import dataclass
from typing import Optional

@dataclass
class Span:
    entity_type: str
    start: int
    end: int

    def overlaps(self, other: Span) -> bool:
        return (
            self.entity_type == other.entity_type
            and self.start < other.end
            and self.end > other.start
        )

    def is_strict_match(self, other: Span) -> bool:
        return (
            self.entity_type == other.entity_type
            and self.start == other.start
            and self.end == other.end
        )

@dataclass
class SampleCounts:
    tp_strict: int = 0
    fp_strict: int = 0
    fn_strict: int = 0
    tp_relaxed: int = 0
    fp_relaxed: int = 0
    fn_relaxed: int = 0

    def precision(self, mode: str = "strict") -> float:
        tp = getattr(self, f"tp_{mode}")
        fp = getattr(self, f"fp_{mode}")
        return tp / (tp + fp) if tp + fp > 0 else 0.0

    def recall(self, mode: str = "strict") -> float:
        tp = getattr(self, f"tp_{mode}")
        fn = getattr(self, f"fn_{mode}")
        return tp / (tp + fn) if tp + fn > 0 else 0.0

    def f1(self, mode: str = "strict") -> float:
        p, r = self.precision(mode), self.recall(mode)
        return 2 * p * r / (p + r) if p + r > 0 else 0.0
